52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic validation for an owner email: a non-empty local part, an '@', and a dotted domain
65	     * whose top-level label is at least two letters. Deliberately conservative so plainly malformed
66	     * input (e.g. a value without an '@') is rejected.
67	     */
68	    private static final Pattern EMAIL_PATTERN =
69	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        rejectBlankOwnerFields(ownerFieldsDto);
118	        normalizeTelephone(ownerFieldsDto);
119	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
120	        normalizeEmail(ownerFieldsDto);
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        if (owner.getRegistrationDate() == null) {
124	            owner.setRegistrationDate(LocalDate.now());
125	        }
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
130	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
136	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
137	        if (currentOwner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        currentOwner.setAddress(ownerFieldsDto.getAddress());
141	        currentOwner.setCity(ownerFieldsDto.getCity());
142	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
143	        currentOwner.setLastName(ownerFieldsDto.getLastName());
144	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
145	        normalizeEmail(ownerFieldsDto);
146	        currentOwner.setEmail(ownerFieldsDto.getEmail());
147	        this.clinicService.saveOwner(currentOwner);
148	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Transactional
153	    @Override
154	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
155	        Owner owner = this.clinicService.findOwnerById(ownerId);
156	        if (owner == null) {
157	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
158	        }
159	        this.clinicService.deleteOwner(owner);
160	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
166	        Owner owner = this.clinicService.findOwnerById(ownerId);
167	        if (owner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        HttpHeaders headers = new HttpHeaders();
171	        Pet pet = petMapper.toPet(petFieldsDto);
172	        owner.setId(ownerId);
173	        pet.setOwner(owner);
174	        pet.getType().setName(null);
175	        this.clinicService.savePet(pet);
176	        PetDto petDto = petMapper.toPetDto(pet);
177	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
178	            .buildAndExpand(pet.getId()).toUri());
179	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
185	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
186	        if (currentOwner != null) {
187	            Pet currentPet = this.clinicService.findPetById(petId);
188	            if (currentPet != null) {
189	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
190	                currentPet.setName(petFieldsDto.getName());
191	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
192	                this.clinicService.savePet(currentPet);
193	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
194	            }
195	        }
196	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
202	        HttpHeaders headers = new HttpHeaders();
203	        Visit visit = visitMapper.toVisit(visitFieldsDto);
204	        Pet pet = new Pet();
205	        pet.setId(petId);
206	        visit.setPet(pet);
207	        this.clinicService.saveVisit(visit);
208	        VisitDto visitDto = visitMapper.toVisitDto(visit);
209	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
210	            .buildAndExpand(visit.getId()).toUri());
211	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
212	    }
213	
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
218	        Owner owner = this.clinicService.findOwnerById(ownerId);
219	        if (owner != null) {
220	            Pet pet = owner.getPet(petId);
221	            if (pet != null) {
222	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
223	            }
224	        }
225	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	    }
227	
228	    /**
229	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
230	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
231	     * the request body already rejects null and empty values, but permits whitespace-only strings
232	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
233	     * that gap so every required field must carry a non-blank value.
234	     *
235	     * @param ownerFieldsDto the submitted owner fields
236	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
237	     */
238	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
239	        List<String> missing = new ArrayList<>();
240	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
241	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
242	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
243	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
244	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
245	        if (!missing.isEmpty()) {
246	            throw new InvalidOwnerFieldsException(missing);
247	        }
248	    }
249	
250	    private void addIfBlank(List<String> missing, String fieldName, String value) {
251	        if (value == null || value.isBlank()) {
252	            missing.add(fieldName);
253	        }
254	    }
255	
256	    /**
257	     * Normalizes the submitted {@code telephone} on create by removing every non-digit character,
258	     * then requires exactly 10 digits to remain. The stripped 10-digit value is written back onto
259	     * the request so it is the value stored and returned. Any input that does not reduce to exactly
260	     * 10 digits is rejected with a {@code 400 Bad Request}.
261	     *
262	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
263	     *                       {@link #rejectBlankOwnerFields} having already run)
264	     * @throws InvalidOwnerFieldsException if the telephone is not exactly 10 digits after stripping
265	     */
266	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
267	        String digits = ownerFieldsDto.getTelephone().replaceAll("\\D", "");
268	        if (digits.length() != 10) {
269	            throw new InvalidOwnerFieldsException(List.of("telephone"));
270	        }
271	        ownerFieldsDto.setTelephone(digits);
272	    }
273	
274	    /**
275	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
276	     * untouched (email is optional). When present it is trimmed and, after validating that it is a
277	     * syntactically valid address, written back lower-cased so it is the value stored and returned.
278	     * Any present-but-invalid address is rejected with a {@code 400 Bad Request}.
279	     *
280	     * @param ownerFieldsDto the submitted owner fields
281	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
282	     */
283	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
284	        String email = ownerFieldsDto.getEmail();
285	        if (email == null || email.isBlank()) {
286	            return;
287	        }
288	        email = email.trim();
289	        if (!EMAIL_PATTERN.matcher(email).matches()) {
290	            throw new InvalidOwnerFieldsException(List.of("email"));
291	        }
292	        ownerFieldsDto.setEmail(email.toLowerCase(Locale.ROOT));
293	    }
294	
295	    /**
296	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
297	     * Every existing owner's stored telephone is normalized the same way (all non-digit characters
298	     * stripped) before comparison, so equality is judged on digits alone. A match is reported as a
299	     * {@code 409 Conflict}.
300	     *
301	     * @param normalizedTelephone the submitted telephone, already reduced to its 10 digits by
302	     *                            {@link #normalizeTelephone}
303	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
304	     */
305	    private void rejectDuplicateTelephone(String normalizedTelephone) {
306	        boolean inUse = this.clinicService.findAllOwners().stream()
307	            .map(Owner::getTelephone)
308	            .filter(Objects::nonNull)
309	            .map(telephone -> telephone.replaceAll("\\D", ""))
310	            .anyMatch(normalizedTelephone::equals);
311	        if (inUse) {
312	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
313	        }
314	    }
315	}
